import type { StorybookConfig } from "@storybook/react-vite";
import tailwindcss from "@tailwindcss/vite";

const config: StorybookConfig = {
	stories: ["../stories/**/*.stories.@(js|jsx|mjs|ts|tsx)"],
	addons: ["@storybook/addon-a11y", "@storybook/addon-docs"],
	core: {
		allowedHosts: ["localhost", "127.0.0.1"],
	},
	framework: "@storybook/react-vite",
	async viteFinal(viteConfig) {
		viteConfig.plugins = [...(viteConfig.plugins ?? []), tailwindcss()];
		return viteConfig;
	},
	typescript: {
		check: true,
		reactDocgen: "react-docgen-typescript",
	},
};

export default config;

@import "@fontsource-variable/schibsted-grotesk";
@import "@fontsource/azeret-mono/latin.css";
@import "tailwindcss";
@import "../theme/index.css";
@import "../components/agent-chat/agent-chat.css";

@source "../components";
@source "../stories";
@source ".";

html,
body,
#storybook-root {
	min-height: 100%;
}

.cline-storybook-surface {
	min-height: 100vh;
	box-sizing: border-box;
	background: var(--background);
	color: var(--foreground);
}

import type { Decorator, Preview } from "@storybook/react-vite";
import "./preview.css";

const withClineTheme: Decorator = (Story, context) => {
	const isDark = context.globals.theme === "dark";
	document.documentElement.classList.toggle("dark", isDark);
	return (
		<div className="cline-storybook-surface">
			<Story />
		</div>
	);
};

const preview: Preview = {
	decorators: [withClineTheme],
	parameters: {
		backgrounds: { disable: true },
		controls: {
			matchers: {
				color: /(background|color)$/i,
				date: /Date$/i,
			},
		},
		layout: "fullscreen",
		viewport: {
			viewports: {
				chatPanel: {
					name: "Chat panel",
					styles: { height: "800px", width: "700px" },
					type: "desktop",
				},
				mobile: {
					name: "Mobile",
					styles: { height: "844px", width: "390px" },
					type: "mobile",
				},
			},
		},
	},
	globalTypes: {
		theme: {
			description: "Cline color theme",
			defaultValue: "dark",
			toolbar: {
				dynamicTitle: true,
				icon: "circlehollow",
				items: [
					{ title: "Light", value: "light" },
					{ title: "Dark", value: "dark" },
				],
			},
		},
	},
};

export default preview;

.cline-ui-agent-approval-card {
	border: 1px solid color-mix(in oklab, var(--border) 80%, transparent);
	border-radius: var(--radius-lg);
	background: color-mix(in oklab, var(--background) 70%, transparent);
	padding: 0.75rem;
}

.cline-ui-agent-approval-card__header {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 0.5rem;
}

.cline-ui-agent-approval-card__title {
	margin: 0;
	color: var(--foreground);
	font-size: var(--text-sm);
	font-weight: var(--font-weight-medium);
	line-height: var(--text-sm--line-height);
	letter-spacing: var(--text-sm--letter-spacing);
}

.cline-ui-agent-approval-card__meta {
	display: inline-flex;
	align-items: center;
	gap: 0.25rem;
	color: var(--muted-foreground);
	font-size: 11px;
}

.cline-ui-agent-approval-card__description {
	margin-top: 0.25rem;
	color: var(--muted-foreground);
	font-size: 11px;
}

.cline-ui-agent-approval-card__detail {
	box-sizing: border-box;
	max-width: 100%;
	max-height: 11rem;
	margin: 0.5rem 0 0;
	overflow-x: hidden;
	overflow-y: auto;
	white-space: pre-wrap;
	overflow-wrap: break-word;
	border: 1px solid color-mix(in oklab, var(--border) 70%, transparent);
	border-radius: var(--radius-md);
	background: var(--background);
	padding: 0.5rem;
	color: var(--muted-foreground);
	font-family: var(--font-mono);
	font-size: var(--text-xs);
	line-height: var(--text-xs--line-height);
	letter-spacing: var(--text-xs--letter-spacing);
}

.cline-ui-agent-approval-card__error {
	margin-top: 0.5rem;
	color: var(--destructive);
	font-size: var(--text-xs);
	line-height: var(--text-xs--line-height);
	letter-spacing: var(--text-xs--letter-spacing);
}

.cline-ui-agent-approval-card__actions {
	display: flex;
	align-items: center;
	gap: 0.5rem;
	margin-top: 0.5rem;
}

.cline-ui-agent-approval-card__button {
	display: inline-flex;
	height: 2rem;
	flex: none;
	align-items: center;
	justify-content: center;
	gap: 0.375rem;
	box-sizing: border-box;
	border-radius: var(--radius-md);
	padding: 0 0.75rem;
	font: inherit;
	font-weight: var(--font-weight-medium);
	white-space: nowrap;
	cursor: pointer;
	transition:
		color 150ms,
		background-color 150ms,
		border-color 150ms,
		box-shadow 150ms;
}

.cline-ui-agent-approval-card__button:focus-visible {
	outline: 3px solid color-mix(in oklab, var(--ring) 50%, transparent);
	outline-offset: 0;
}

.cline-ui-agent-approval-card__button:disabled {
	pointer-events: none;
	opacity: 0.5;
}

.cline-ui-agent-approval-card__button--approve {
	border: 0;
	background: var(--primary);
	color: var(--primary-foreground);
}

.cline-ui-agent-approval-card__button--approve:hover {
	background: color-mix(in oklab, var(--primary) 90%, transparent);
}

.cline-ui-agent-approval-card__button--reject {
	border: 1px solid var(--border);
	background: var(--background);
	color: var(--foreground);
	box-shadow: 0 1px 2px 0 rgb(0 0 0 / 5%);
}

.cline-ui-agent-approval-card__button--reject:hover {
	background: var(--accent);
	color: var(--accent-foreground);
}

.dark .cline-ui-agent-approval-card__button--reject {
	border-color: var(--input);
	background: color-mix(in oklab, var(--input) 30%, transparent);
}

.dark .cline-ui-agent-approval-card__button--reject:hover {
	background: color-mix(in oklab, var(--input) 50%, transparent);
}

.cline-ui-agent-approval-card__spinner {
	width: 0.875rem;
	height: 0.875rem;
	margin-right: 0.25rem;
	animation: cline-ui-agent-approval-card-spin 1s linear infinite;
	fill: none;
	stroke: currentColor;
	stroke-linecap: round;
	stroke-linejoin: round;
	stroke-width: 2;
}

.cline-ui-agent-approval-card__button:has(
		> .cline-ui-agent-approval-card__spinner
	) {
	padding-inline: 0.625rem;
}

@keyframes cline-ui-agent-approval-card-spin {
	to {
		transform: rotate(360deg);
	}
}

@media (prefers-reduced-motion: reduce) {
	.cline-ui-agent-approval-card__spinner {
		animation: none;
	}
}

"use client";

import { type ReactNode, useId } from "react";

export type AgentApprovalAction = "approve" | "reject";

export interface AgentApprovalCardProps {
	description?: ReactNode;
	detail?: ReactNode;
	error?: ReactNode;
	meta?: ReactNode;
	onApprove: () => void;
	onReject: () => void;
	responding?: AgentApprovalAction;
	title: ReactNode;
}

function Spinner() {
	return (
		<svg
			aria-hidden="true"
			className="cline-ui-agent-approval-card__spinner"
			viewBox="0 0 24 24"
		>
			<path d="M21 12a9 9 0 1 1-6.219-8.56" />
		</svg>
	);
}

export function AgentApprovalCard({
	description,
	detail,
	error,
	meta,
	onApprove,
	onReject,
	responding,
	title,
}: AgentApprovalCardProps) {
	const titleId = useId();
	const isPending = responding !== undefined;

	return (
		<section
			aria-busy={isPending || undefined}
			aria-labelledby={titleId}
			className="cline-ui-agent-approval-card"
		>
			<div className="cline-ui-agent-approval-card__header">
				<div className="cline-ui-agent-approval-card__title" id={titleId}>
					{title}
				</div>
				{meta ? (
					<div className="cline-ui-agent-approval-card__meta">{meta}</div>
				) : null}
			</div>
			{description ? (
				<div className="cline-ui-agent-approval-card__description">
					{description}
				</div>
			) : null}
			{detail != null ? (
				<pre className="cline-ui-agent-approval-card__detail">{detail}</pre>
			) : null}
			{error ? (
				<div className="cline-ui-agent-approval-card__error">{error}</div>
			) : null}
			<div className="cline-ui-agent-approval-card__actions">
				<button
					className="cline-ui-agent-approval-card__button cline-ui-agent-approval-card__button--approve"
					disabled={isPending}
					onClick={onApprove}
					type="button"
				>
					{responding === "approve" ? (
						<>
							<Spinner />
							Approving...
						</>
					) : (
						"Approve"
					)}
				</button>
				<button
					className="cline-ui-agent-approval-card__button cline-ui-agent-approval-card__button--reject"
					disabled={isPending}
					onClick={onReject}
					type="button"
				>
					{responding === "reject" ? (
						<>
							<Spinner />
							Rejecting...
						</>
					) : (
						"Reject"
					)}
				</button>
			</div>
		</section>
	);
}

.cline-ui-agent-aurora {
	position: absolute;
	inset: 0;
	overflow: hidden;
	pointer-events: none;
}

.cline-ui-agent-aurora__horizon,
.cline-ui-agent-aurora__current,
.cline-ui-agent-aurora__blob,
.cline-ui-agent-aurora__star {
	position: absolute;
}

/* Avoid filter: blur; it forced full-surface repaints below 10fps. */
.cline-ui-agent-aurora__soft-band {
	-webkit-mask-image: linear-gradient(
		to bottom,
		transparent,
		black 32%,
		black 68%,
		transparent
	);
	mask-image: linear-gradient(
		to bottom,
		transparent,
		black 32%,
		black 68%,
		transparent
	);
}

.cline-ui-agent-aurora__horizon {
	right: -8%;
	bottom: -3%;
	left: -8%;
	height: 40%;
	background: linear-gradient(
		90deg,
		color-mix(in oklab, var(--brand-lilac) 58%, transparent),
		color-mix(in oklab, var(--brand-magenta) 62%, transparent) 42%,
		color-mix(in oklab, var(--brand-periwinkle) 72%, transparent) 78%,
		color-mix(in oklab, var(--brand-cyan) 58%, transparent)
	);
	opacity: 0.6;
	animation: cline-ui-agent-aurora-horizon 8s ease-in-out -3s infinite alternate;
	transform-origin: center bottom;
	will-change: opacity, transform;
}

.cline-ui-agent-aurora__current {
	animation-name: cline-ui-agent-aurora-current;
	animation-timing-function: ease-in-out;
	animation-iteration-count: infinite;
	animation-direction: alternate;
	will-change: opacity, transform;
}

.cline-ui-agent-aurora__current--left {
	bottom: 3%;
	left: -45%;
	width: 125%;
	height: 30%;
	background: linear-gradient(
		105deg,
		transparent 12%,
		color-mix(in oklab, var(--brand-magenta) 66%, transparent) 38%,
		color-mix(in oklab, var(--brand-periwinkle) 72%, transparent) 58%,
		transparent 82%
	);
	opacity: 0.5;
	animation-duration: 9s;
	animation-delay: -2s;
}

.cline-ui-agent-aurora__current--right {
	right: -42%;
	bottom: -5%;
	width: 120%;
	height: 34%;
	background: linear-gradient(
		75deg,
		transparent 10%,
		color-mix(in oklab, var(--brand-cyan) 62%, transparent) 42%,
		color-mix(in oklab, var(--brand-violet) 70%, transparent) 64%,
		transparent 88%
	);
	opacity: 0.45;
	animation-duration: 12s;
	animation-delay: -6s;
	animation-direction: alternate-reverse;
}

.cline-ui-agent-aurora__blob {
	animation-name: cline-ui-agent-aurora-drift;
	animation-timing-function: ease-in-out;
	animation-iteration-count: infinite;
	animation-direction: alternate;
	will-change: opacity, transform;
}

.cline-ui-agent-aurora__blob--left {
	bottom: -40%;
	left: -20%;
	width: 70%;
	height: 80%;
}

.cline-ui-agent-aurora__blob--right {
	right: -15%;
	bottom: -40%;
	width: 65%;
	height: 85%;
	animation-name: cline-ui-agent-aurora-drift-reverse;
}

.cline-ui-agent-aurora__star {
	border-radius: 1px;
	animation-name: cline-ui-agent-aurora-twinkle;
	animation-timing-function: ease-in-out;
	animation-iteration-count: infinite;
}

@media (prefers-reduced-motion: reduce) {
	.cline-ui-agent-aurora__blob,
	.cline-ui-agent-aurora__current,
	.cline-ui-agent-aurora__horizon,
	.cline-ui-agent-aurora__star {
		/* biome-ignore lint/complexity/noImportantStyles: overrides inline timing */
		animation: none !important;
	}

	.cline-ui-agent-aurora__horizon {
		opacity: 0.68;
		transform: translate3d(0, -1%, 0) scale(1.05);
	}

	.cline-ui-agent-aurora__blob,
	.cline-ui-agent-aurora__current {
		opacity: 0.58;
		transform: none;
	}

	.cline-ui-agent-aurora__blob,
	.cline-ui-agent-aurora__current,
	.cline-ui-agent-aurora__horizon {
		will-change: auto;
	}
}

@keyframes cline-ui-agent-aurora-drift {
	0% {
		opacity: 0.55;
		transform: translate3d(-8%, 5%, 0) scale(0.94);
	}

	50% {
		opacity: 0.92;
		transform: translate3d(13%, -10%, 0) scale(1.11);
	}

	100% {
		opacity: 0.62;
		transform: translate3d(-5%, -2%, 0) scale(1.02);
	}
}

@keyframes cline-ui-agent-aurora-drift-reverse {
	0% {
		opacity: 0.62;
		transform: translate3d(10%, -6%, 0) scale(1.08);
	}

	50% {
		opacity: 0.9;
		transform: translate3d(-12%, -12%, 0) scale(0.96);
	}

	100% {
		opacity: 0.58;
		transform: translate3d(6%, 2%, 0) scale(1.04);
	}
}

@keyframes cline-ui-agent-aurora-horizon {
	0% {
		opacity: 0.48;
		transform: translate3d(-3%, 9%, 0) scale(0.96, 0.84);
	}

	50% {
		opacity: 0.88;
		transform: translate3d(3%, -5%, 0) scale(1.08, 1.16);
	}

	100% {
		opacity: 0.58;
		transform: translate3d(-1%, 2%, 0) scale(1.02, 0.96);
	}
}

@keyframes cline-ui-agent-aurora-current {
	0% {
		opacity: 0.28;
		transform: translate3d(-16%, 8%, 0) scaleX(0.84);
	}

	50% {
		opacity: 0.72;
		transform: translate3d(17%, -8%, 0) scaleX(1.08);
	}

	100% {
		opacity: 0.38;
		transform: translate3d(28%, 4%, 0) scaleX(0.94);
	}
}

@keyframes cline-ui-agent-aurora-twinkle {
	0%,
	100% {
		opacity: 0.15;
	}

	50% {
		opacity: 0.78;
	}
}

"use client";

interface AuroraStar {
	color: string;
	delay: string;
	duration: string;
	left: string;
	opacity: number;
	size: number;
	top: string;
}

const BLOBS = [
	{
		delay: "0s",
		gradient:
			"radial-gradient(ellipse at center, color-mix(in oklab, var(--brand-periwinkle) 64%, transparent), color-mix(in oklab, var(--brand-periwinkle) 30%, transparent) 42%, transparent 70%)",
		id: "periwinkle-left",
		position: "left",
		duration: "11s",
	},
	{
		delay: "-12s",
		gradient:
			"radial-gradient(ellipse at center, color-mix(in oklab, var(--brand-violet) 58%, transparent), color-mix(in oklab, var(--brand-violet) 27%, transparent) 42%, transparent 70%)",
		id: "violet-right",
		position: "right",
		duration: "12.5s",
	},
] as const;

function seededUnit(index: number, salt: number): number {
	let value =
		Math.imul(index + 1, 0x9e3779b1) ^ Math.imul(salt + 1, 0x85ebca6b);
	value ^= value >>> 16;
	value = Math.imul(value, 0x7feb352d);
	value ^= value >>> 15;
	value = Math.imul(value, 0x846ca68b);
	value ^= value >>> 16;
	return (value >>> 0) / 0x1_0000_0000;
}

const STARS = Array.from({ length: 32 }, (_, index): AuroraStar => {
	const vertical = seededUnit(index, 1);
	const size = seededUnit(index, 3);
	return {
		color:
			seededUnit(index, 7) > 0.78
				? "var(--brand-cyan)"
				: "color-mix(in oklab, white 92%, var(--brand-lilac))",
		delay: `${seededUnit(index, 4) * -5}s`,
		duration: `${3.5 + seededUnit(index, 5) * 3.5}s`,
		left: `${seededUnit(index, 2) * 100}%`,
		opacity: 0.35 + seededUnit(index, 6) * 0.6,
		size: size < 0.14 ? 4 : size < 0.52 ? 3 : 2,
		top: `${100 - (1 - vertical * vertical) * 45}%`,
	};
});

/** Decorative layer that fills its nearest positioned ancestor. */
export function AgentAurora() {
	return (
		<div aria-hidden="true" className="cline-ui-agent-aurora">
			<div className="cline-ui-agent-aurora__horizon cline-ui-agent-aurora__soft-band" />
			<div className="cline-ui-agent-aurora__current cline-ui-agent-aurora__current--left cline-ui-agent-aurora__soft-band" />
			<div className="cline-ui-agent-aurora__current cline-ui-agent-aurora__current--right cline-ui-agent-aurora__soft-band" />
			{BLOBS.map((blob) => (
				<div
					className={`cline-ui-agent-aurora__blob cline-ui-agent-aurora__blob--${blob.position}`}
					key={blob.id}
					style={{
						animationDelay: blob.delay,
						animationDuration: blob.duration,
						background: blob.gradient,
					}}
				/>
			))}
			{STARS.map((star) => (
				<span
					className="cline-ui-agent-aurora__star"
					key={`${star.left}-${star.top}`}
					style={{
						animationDelay: star.delay,
						animationDuration: star.duration,
						background: star.color,
						height: star.size,
						left: star.left,
						opacity: star.opacity,
						top: star.top,
						width: star.size,
					}}
				/>
			))}
		</div>
	);
}

@layer components {
	.cline-chat-conversation {
		position: relative;
		display: flex;
		min-width: 0;
		min-height: 0;
		flex: 1 1 auto;
		overflow: hidden;
		color: var(--foreground);
	}

	.cline-chat-conversation-viewport {
		width: 100%;
		min-width: 0;
		min-height: 0;
		overflow-x: hidden;
		overflow-y: auto;
	}

	.cline-chat-conversation-content {
		display: flex;
		width: 100%;
		min-width: 0;
		min-height: 100%;
		flex-direction: column;
		gap: 0.5rem;
		box-sizing: border-box;
	}

	.cline-chat-empty-state {
		display: flex;
		width: 100%;
		min-height: 16rem;
		align-items: center;
		justify-content: center;
		flex-direction: column;
		gap: 0.75rem;
		padding: 2rem;
		box-sizing: border-box;
		color: var(--muted-foreground);
		text-align: center;
	}

	.cline-chat-empty-state-icon {
		display: grid;
		place-items: center;
	}

	.cline-chat-empty-state h3,
	.cline-chat-empty-state p {
		margin: 0;
	}

	.cline-chat-empty-state h3 {
		color: var(--foreground);
		font-size: var(--text-sm);
		font-weight: var(--font-weight-medium);
	}

	.cline-chat-empty-state p {
		margin-top: 0.25rem;
		font-size: var(--text-sm);
	}

	.cline-chat-scroll-button {
		position: absolute;
		right: 1rem;
		bottom: 1rem;
		z-index: 20;
		display: grid;
		width: 2.25rem;
		height: 2.25rem;
		place-items: center;
		padding: 0;
		border: 1px solid var(--border);
		border-radius: 9999px;
		background: var(--secondary);
		box-shadow: 0 1px 3px rgb(0 0 0 / 0.12);
		color: var(--secondary-foreground);
		font: inherit;
		cursor: pointer;
	}

	.cline-chat-scroll-button:hover {
		background: var(--accent);
		color: var(--accent-foreground);
	}

	.cline-chat-message {
		display: flex;
		width: 100%;
		min-width: 0;
		flex-direction: column;
		align-items: flex-start;
		gap: 0.25rem;
		font-size: var(--text-sm);
		overflow-wrap: anywhere;
	}

	.cline-chat-message[data-role="user"] {
		align-items: flex-end;
	}

	.cline-chat-message-content {
		max-width: 100%;
		min-width: 0;
		box-sizing: border-box;
		overflow: hidden;
		color: var(--foreground);
	}

	.cline-chat-message[data-role="user"] > .cline-chat-message-content {
		max-width: 85%;
		padding: 0.5rem;
		border-radius: calc(var(--radius) - 4px);
		background: var(--card);
		color: color-mix(in oklab, var(--foreground) 80%, transparent);
	}

	.cline-chat-message[data-role="error"] > .cline-chat-message-content {
		padding: 0.75rem;
		border: 1px solid color-mix(in oklab, var(--destructive) 40%, transparent);
		border-radius: var(--radius);
		background: color-mix(in oklab, var(--destructive) 10%, transparent);
		color: var(--destructive);
	}

	.cline-chat-message[data-role="system"] > .cline-chat-message-content,
	.cline-chat-message[data-role="status"] > .cline-chat-message-content {
		color: var(--muted-foreground);
	}

	.cline-chat-message-actions {
		display: flex;
