		display: inline-flex;
		min-width: 1.5rem;
		height: 1.5rem;
		align-items: center;
		justify-content: center;
		gap: 0.375rem;
		padding: 0 0.5rem;
		border: 0;
		border-radius: calc(var(--radius) - 4px);
		background: transparent;
		color: var(--muted-foreground);
		font: inherit;
		font-size: var(--text-xs);
		cursor: pointer;
