import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const packageRoot = join(import.meta.dir, "..");
const sourcePath = join(packageRoot, "theme", "tokens.css");
const outputPath = join(packageRoot, "theme", "scoped-tokens.css");
const checkOnly = process.argv.includes("--check");
const generatedHeader = `/*
 * Generated by scripts/generate-theme.ts from theme/tokens.css.
 * Edit tokens.css, then run \`bun run generate:theme\`.
 */

`;

function replaceSelector(
	source: string,
	selector: string,
	replacement: string,
): string {
	const ruleStart = `${selector} {`;
	if (source.split(ruleStart).length !== 2) {
		throw new Error(`${ruleStart} must occur exactly once in ${sourcePath}`);
	}
	return source.replace(ruleStart, `${replacement} {`);
}

const source = readFileSync(sourcePath, "utf8");
const sourceWithoutHeader = source.replace(/^\/\*[\s\S]*?\*\/\s*/, "");
if (sourceWithoutHeader === source) {
	throw new Error(`${sourcePath} must start with a contract comment`);
}
const generated =
	generatedHeader +
	replaceSelector(
		replaceSelector(sourceWithoutHeader, ":root", ".cline-ui-theme"),
		".dark",
		".dark .cline-ui-theme,\n.cline-ui-theme.dark",
	);

if (checkOnly) {
	if (readFileSync(outputPath, "utf8") !== generated) {
		throw new Error(`${outputPath} is out of date`);
	}
	console.log("@cline/ui generated theme file is current");
} else {
	writeFileSync(outputPath, generated);
	console.log("Generated @cline/ui scoped theme");
}

import {
	mkdirSync,
	mkdtempSync,
	readdirSync,
	rmSync,
	writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { basename, join, resolve } from "node:path";

const packageRoot = join(import.meta.dir, "..");
const importCheck = `
import { existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import {
	AgentApprovalCard,
	AgentAurora,
	AgentHeroHeading,
	AgentQuickActions,
	SearchCombobox,
	SessionStatus,
} from "@cline/ui";
import { Conversation, Message } from "@cline/ui/components/agent-chat";

for (const specifier of [
	"@cline/ui/components.css",
	"@cline/ui/components/markdown.css",
	"@cline/ui/theme/scoped-tokens.css",
]) {
	if (!existsSync(fileURLToPath(import.meta.resolve(specifier)))) {
		throw new Error("packed CSS export does not exist: " + specifier);
	}
}

const css = import.meta.resolve("@cline/ui/components/agent-chat.css");
const tokens = import.meta.resolve("@cline/ui/theme/tokens.css");
if (
	!AgentApprovalCard ||
	!AgentAurora ||
	!AgentHeroHeading ||
	!SearchCombobox ||
	!AgentQuickActions ||
	!SessionStatus ||
	!Conversation ||
	!Message ||
	!css ||
	!tokens
) {
	process.exit(1);
}
`;

async function run(command: string[], cwd: string): Promise<void> {
	const child = Bun.spawn(command, {
		cwd,
		stderr: "inherit",
		stdout: "inherit",
	});
	const exitCode = await child.exited;
	if (exitCode !== 0) {
		throw new Error(`${command.join(" ")} exited with ${exitCode}`);
	}
}

function createConsumer(root: string): void {
	mkdirSync(root, { recursive: true });
	writeFileSync(
		join(root, "package.json"),
		`${JSON.stringify({ name: "cline-ui-smoke", private: true, type: "module" }, null, 2)}\n`,
	);
}

const temporaryRoot = mkdtempSync(join(tmpdir(), "cline-ui-package-"));

try {
	let archive = process.argv[2] ? resolve(process.argv[2]) : undefined;
	if (!archive) {
		const packDirectory = join(temporaryRoot, "pack");
		mkdirSync(packDirectory, { recursive: true });
		await run(
			[
				process.execPath,
				"pm",
				"pack",
				"--ignore-scripts",
				"--destination",
				packDirectory,
			],
			packageRoot,
		);
		const archiveName = readdirSync(packDirectory).find((name) =>
			name.endsWith(".tgz"),
		);
		if (!archiveName) throw new Error("bun pm pack did not create an archive");
		archive = join(packDirectory, archiveName);
	}

	const bunConsumer = join(temporaryRoot, "bun-consumer");
	createConsumer(bunConsumer);
	await run(
		[process.execPath, "add", "--ignore-scripts", archive, "react@19.2.4"],
		bunConsumer,
	);
	await run([process.execPath, "-e", importCheck], bunConsumer);

	const npmConsumer = join(temporaryRoot, "npm-consumer");
	createConsumer(npmConsumer);
	await run(
		[
			"npm",
			"install",
			"--ignore-scripts",
			"--no-audit",
			"--no-fund",
			archive,
			"react@18.3.1",
		],
		npmConsumer,
	);
	await run(["node", "--input-type=module", "-e", importCheck], npmConsumer);
	console.log(
		`Verified packed ${basename(archive)} with Bun/React 19 and npm/Node/React 18`,
	);
} finally {
	rmSync(temporaryRoot, { force: true, recursive: true });
}

import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";

const packageRoot = join(import.meta.dir, "..");
const readThemeFile = (name: string) =>
	readFileSync(join(packageRoot, "theme", name), "utf8");

const tokens = readThemeFile("tokens.css");
const tokensWithoutComments = tokens.replace(/\/\*[\s\S]*?\*\//g, "");
const theme = readThemeFile("theme.css");
const base = readThemeFile("base.css");
const index = readThemeFile("index.css");
const manifest = JSON.parse(
	readFileSync(join(packageRoot, "package.json"), "utf8"),
) as { exports?: Record<string, string> };

const requiredTokens = [
	"--background",
	"--foreground",
	"--primary",
	"--border",
	"--font-sans",
	"--font-mono",
	"--font-weight-normal",
	"--text-xs",
	"--text-6xl",
	"--sidebar",
];

for (const token of requiredTokens) {
	if (!tokens.includes(`${token}:`)) {
		throw new Error(`tokens.css is missing ${token}`);
	}
}

if (
	tokens.includes("--cline-") ||
	theme.includes("--cline-") ||
	base.includes("--cline-")
) {
	throw new Error("theme contract must not expose --cline-* variables");
}
if (/@(?:apply|custom-variant|layer|theme)\b/.test(tokensWithoutComments)) {
	throw new Error("tokens.css must remain framework-neutral");
}
if (theme.includes("tokens.css") || !theme.includes("@theme inline")) {
	throw new Error(
		"theme.css must contain only the Tailwind mapping and variants",
	);
}
if (base.includes("#__next") || base.includes("@source")) {
	throw new Error("base.css must not contain consumer-specific shell policy");
}
if (
	!index.includes('@import "./tokens.css";') ||
	!index.includes('@import "./theme.css";') ||
	!index.includes('@import "./base.css";')
) {
	throw new Error("theme entry point must compose tokens, theme, and base CSS");
}
for (const subpath of [
	"./components.css",
	"./components/markdown.css",
	"./theme/index.css",
	"./theme/scoped-tokens.css",
	"./theme/tokens.css",
	"./theme/theme.css",
	"./theme/base.css",
]) {
	const target = manifest.exports?.[subpath];
	if (!target || !existsSync(join(packageRoot, target))) {
		throw new Error(`package.json export ${subpath} is missing or invalid`);
	}
}

console.log("@cline/ui theme contract is valid");

